window.addBankLesson('bank_math_geom_u5_l5', 'math', 'خواص الشكل الرباعي الدائري', [
    // --- 40 MCQ ---
    [1, 'mcq', '', 'من الخواص الأساسية والمؤكدة لأي شكل رباعي دائري أن كل زاويتين متقابلتين فيه تكونان:', ['متتامتان ومجموع قياسيهما تسعون درجة تماماً', 'متساويتان في القياس الهندسي مهما اختلف الشكل', 'متكاملتان ومجموع قياسيهما مائة وثمانون درجة', 'منعكستان ومجموع قياسيهما ثلاثمائة وستون درجة'], 2],
    [2, 'mcq', '', 'في الشكل الرباعي الدائري أ ب جـ د، إذا كان قياس زاوية (أ) = 70 درجة، فإن قياس الزاوية المقابلة (جـ) يساوي:', ['عشرين درجة هندسية لتتمم الزاوية المعطاة', 'سبعين درجة هندسية لتتساوى مع الزاوية المعطاة', 'مائة وعشر درجات هندسية لتكمل الزاوية المعطاة', 'مائتين وتسعين درجة هندسية للزاوية المنعكسة'], 2], // 180 - 70 = 110
    [3, 'mcq', '', 'قياس الزاوية الخارجة عند أي رأس من رؤوس الشكل الرباعي الدائري يساوي دائماً:', ['قياس الزاوية الداخلة المجاورة لها مباشرة في الشكل', 'قياس الزاوية الداخلة المقابلة للمجاورة لها في الشكل', 'مجموع قياسات الزوايا الثلاث الأخرى في الشكل الرباعي', 'نصف قياس الزاوية الداخلة المقابلة لها في الشكل'], 1],
    [4, 'mcq', '', 'في الشكل الرباعي الدائري، أي زاويتين مرسومتين على قاعدة واحدة وفي جهة واحدة منها تكونان:', ['متكاملتين ومجموع قياسيهما مائة وثمانون درجة', 'مختلفتين في القياس حسب زاوية ميل القاعدة المذكورة', 'متساويتين في القياس الهندسي بشكل مؤكد وثابت', 'متتامتين ومجموع قياسيهما تسعون درجة هندسية'], 2],
    [5, 'mcq', '', 'إذا كان الشكل أ ب جـ د رباعياً دائرياً، وكانت زاوية أ ب د = 40 درجة، فإن الزاوية أ جـ د تساوي:', ['أربعين درجة هندسية لاشتراكهما في القاعدة أ د', 'خمسين درجة هندسية كمتممة للزاوية المحيطية المعطاة', 'مائة وأربعين درجة هندسية كمكملة للزاوية المحيطية المعطاة', 'ثمانين درجة هندسية كضعف للزاوية المحيطية المشتركة'], 0], // مشتركتان في القاعدة أ د
    [6, 'mcq', '', 'أ ب جـ د رباعي دائري، قياس زاوية أ = 3 س، وقياس زاوية جـ (المقابلة لها) = 2 س. فإن قيمة س تساوي:', ['ثلاثين درجة هندسية لتكامل الزاويتين', 'ستة وثلاثين درجة هندسية لتطابق الزاويتين', 'ستاً وثلاثين درجة هندسية لحل المعادلة الخطية', 'عشرين درجة هندسية لتتميم الزاويتين المعطاتين'], 2], // 3س + 2س = 180 => 5س = 180 => س = 36
    [7, 'mcq', '', 'استكمالاً للسؤال السابق، قياس الزاوية أ الفعلي يساوي:', ['اثنتين وسبعين درجة هندسية دقيقة (72 درجة)', 'مائة وثماني درجات هندسية دقيقة (108 درجات)', 'تسعين درجة هندسية تمثل زاوية قائمة تماماً', 'مائة وثمانين درجة هندسية تمثل زاوية مستقيمة'], 1], // 3 * 36 = 108
    [8, 'mcq', '', 'أ ب جـ د رباعي دائري، الزاوية الخارجة عند الرأس ب تساوي 100 درجة، فإن قياس الزاوية د (الداخلة المقابلة للمجاورة) تساوي:', ['ثمانين درجة هندسية كمكملة للزاوية المجاورة', 'مائة درجة هندسية لمطابقتها الزاوية الخارجة', 'خمسين درجة هندسية لتمثل نصف الزاوية الخارجة', 'مائتين وستين درجة هندسية لتمثل الزاوية المنعكسة'], 1], // الخارجة = الداخلة المقابلة للمجاورة = 100
    [9, 'mcq', '', 'في الرباعي الدائري، إذا تساوت زاويتان متقابلتان في القياس، فإن قياس كل منهما يجب أن يساوي:', ['خمس وأربعين درجة كزاوية حادة مقسمة للزاوية القائمة', 'تسعين درجة كزاوية قائمة ناتجة عن تكاملهما وتساويهما', 'مائة وعشرين درجة كزاوية منفرجة تمثل ثلث الدائرة', 'مائة وثمانين درجة كزاوية مستقيمة تمثل نصف الدائرة'], 1], // س + س = 180 => 2س = 180 => س = 90
    [10, 'mcq', '', 'أي شكل رباعي دائري زاويتاه المتقابلتان متساويتان يعتبر بالضرورة:', ['متوازي أضلاع عادي تميل زواياه بزاوية حادة', 'معيناً متطابق الأضلاع وتتقاطع أقطاره بتعامد', 'مستطيلاً أو مربعاً لكون جميع زواياه الداخلية قوائم', 'شبه منحرف غير منتظم تختلف فيه جميع القياسات'], 2],
    [11, 'mcq', '', 'أ ب جـ د رباعي دائري، أ جـ يمثل قطراً في الدائرة. فإن قياس زاوية أ ب جـ يساوي:', ['ستين درجة هندسية تمثل زاوية المثلث المذكور', 'تسعين درجة هندسية لأنها محيطية مرسومة في نصف دائرة', 'مائة وعشرين درجة هندسية كزاوية مكملة للزوايا الأخرى', 'مائة وثمانين درجة هندسية للتقابل مع القطر الأساسي'], 1],
    [12, 'mcq', '', 'في الرباعي الدائري المربع، قياس الزاوية المحصورة بين الضلع والقطر تساوي:', ['ثلاثين درجة هندسية مقسمة من الزاوية القائمة', 'خمسة وأربعين درجة هندسية كنصف للزاوية القائمة', 'ستين درجة هندسية لتشكيل مثلث متساوي الأضلاع', 'تسعين درجة هندسية للتقاطع العمودي الدقيق'], 1], // 90 / 2 = 45
    [13, 'mcq', '', 'إذا كانت أ ب جـ د نقاطاً على محيط دائرة، وكان قياس زاوية أ ب د = 30، وزاوية د ب جـ = 50. فإن الزاوية أ د جـ تساوي:', ['ثمانين درجة هندسية كجمع للزاويتين المتجاورتين', 'مائة درجة هندسية لتكملة الزاوية المتقابلة معها', 'خمسين درجة هندسية لتبادلها مع إحدى الزوايا المذكورة', 'مائة وثلاثين درجة لتتمم مجموع زوايا المثلث المعطى'], 1], // زاوية أ ب جـ = 30 + 50 = 80. الزاوية المقابلة أ د جـ = 180 - 80 = 100
    [14, 'mcq', '', 'قياس الزاوية الخارجة للرباعي الدائري المنتظم (المربع) عند أي رأس يساوي:', ['خمسة وأربعين درجة هندسية فقط', 'تسعين درجة هندسية مطابقة للزاوية الداخلية', 'مائة وعشرين درجة هندسية كزاوية منفرجة', 'مائة وثمانين درجة كزاوية مستقيمة كاملة'], 1], // الزاوية الداخلة 90، الخارجة = 180 - 90 = 90 (وهي تساوي المقابلة للمجاورة 90)
    [15, 'mcq', '', 'أ ب جـ د رباعي دائري، زاوية ب = 110. رسم المماس س ص عند أ. هل يمكن تحديد زاوية د؟', ['نعم، وتساوي سبعين درجة لتكملة الزاوية ب المتقابلة', 'لا، لا يمكن تحديدها دون معرفة زوايا المماس الأساسية', 'نعم، وتساوي مائة وعشر درجات للتطابق المباشر', 'نعم، وتساوي عشرين درجة كزاوية حادة مكملة للتماس'], 0], // د تقابل ب. 180 - 110 = 70
    [16, 'mcq', '', 'أ ب جـ د شكل رباعي دائري. إذا تقاطع القطران أ جـ، ب د في النقطة هـ، فإن المثلثين أ هـ ب و د هـ جـ:', ['متطابقان تماماً في الأطوال والمساحات بجميع الأشكال', 'متشابهان لوجود زوايا محيطية متساوية وزوايا متقابلة بالرأس', 'قائما الزاوية في نقطة التقاطع المركزية بصورة دائمة', 'لا توجد بينهما أي علاقة رياضية قابلة للإثبات'], 1], // زاوية أ ب د = أ جـ د، وزاوية ب أ جـ = ب د جـ، إذن يتشابهان
    [17, 'mcq', '', 'إذا كانت زاوية أ جـ د = 60 وزاوية أ ب د = 60، وهما مرسومتان على القاعدة أ د، فإن خواص الشكل أ ب جـ د:', ['يطابق خواص متوازي الأضلاع ذو الزوايا الحادة المتوالية', 'تعتبر خواص شكل رباعي دائري لوجود زاويتين متساويتين على قاعدة', 'تنفي دائرية الشكل لاختلاف جهة القاعدة المشتركة للزوايا', 'تجعله شبه منحرف قائم الزاوية في الرأسين المتقابلين'], 1],
    [18, 'mcq', '', 'في الرباعي الدائري أ ب جـ د، إذا كان أ ب يوازي د جـ، فإن:', ['زاوية أ تساوي زاوية د بالتبادل المباشر للخطوط', 'زاوية أ تكمل زاوية د (مجموعهما 180) لأنهما متداخلتان، وبما أن أ تكمل جـ، فإن جـ = د', 'القطران أ جـ و ب د متعامدان ومتساويان في الطول الجبري', 'الشكل يمثل طائرة ورقية ذات أضلاع متقابلة غير متوازية'], 1], // أ تكمل د (تداخل). أ تكمل جـ (تقابل في دائري). إذن جـ = د (شكل شبه منحرف متساوي الساقين)
    [19, 'mcq', '', 'إذا توازى ضلعان متقابلان في رباعي دائري، فإنه يتحول بالضرورة إلى:', ['متوازي أضلاع مائل الزوايا ولا يحقق شروط الدائرة', 'معين ذي أقطار متعامدة ولا تتطابق زواياه الداخلية', 'شبه منحرف متساوي الساقين (أو مستطيل/مربع كحالات خاصة)', 'شبه منحرف قائم الزاوية في رأسين متتاليين تماماً'], 2],
    [20, 'mcq', '', 'في الرباعي الدائري، مجموع قياسات الزوايا الخارجية الأربع (بأخذ زاوية واحدة عند كل رأس) يساوي:', ['مائة وثمانين درجة كأي مثلث مسطح', 'ثلاثمائة وستين درجة كأي شكل مضلع محدب', 'سبعمائة وعشرين درجة كشكل سداسي', 'خمسمائة وأربعين درجة كشكل خماسي'], 1], // مجموع الزوايا الخارجية لأي مضلع محدب = 360
    [21, 'mcq', '', 'أ ب جـ د رباعي دائري، زاوية أ = زاوية جـ. فإن نوع الزاويتين:', ['حادتان مجموعهما مائة وثمانون درجة هندسية', 'منفرجتان مجموعهما ثلاثمائة وستون درجة', 'قائمتان قياس كل منهما تسعون درجة هندسية', 'منعكستان لتشكيل زاوية الدائرة الكاملة'], 2],
    [22, 'mcq', '', 'إذا كان قياس زاوية أ = 50 في رباعي دائري، فإن الزاوية الخارجية عند الرأس جـ تساوي:', ['مائة وثلاثين درجة لتكملة الزاوية أ المتقابلة', 'خمسين درجة لمطابقة الزاوية الداخلة المقابلة للمجاورة', 'أربعين درجة لتتميم الزاوية أ المقابلة لها هندسياً', 'مائة درجة كضعف الزاوية أ المذكورة في السؤال'], 1], // الخارجة عند جـ = الداخلة عند أ = 50
    [23, 'mcq', '', 'أ ب جـ د رباعي دائري. القوس أ ب = القوس ب جـ. فإن:', ['الزاوية المحيطية أ د ب تساوي الزاوية المحيطية ب د جـ', 'الزاوية المحيطية أ جـ ب تكمل الزاوية المحيطية د أ جـ', 'الوتر أ د يساوي الوتر جـ د كخاصية مباشرة للأقواس', 'القطران أ جـ و ب د يتقاطعان في المركز تماماً'], 0], // الأقواس المتساوية تحصر زوايا محيطية متساوية
    [24, 'mcq', '', 'إذا كانت إحدى الزوايا في رباعي دائري قياسها 120 درجة، فإن الزاوية المقابلة لها قياسها:', ['ستون درجة لتكملة مجموع مائة وثمانين درجة', 'مائة وعشرون درجة لتتطابق مع الزاوية المعطاة', 'تسعون درجة كزاوية قائمة منفصلة عن الشكل', 'ثلاثون درجة كربع القياس المعطى في السؤال'], 0], // 180 - 120 = 60
    [25, 'mcq', '', 'أ ب جـ د رباعي دائري، تقاطع القطران في م. زاوية ب أ جـ = زاوية د أ جـ = 30. فإن القوس ب جـ يطابق القوس:', ['أ ب لأنه يشترك في القاعدة الرئيسية للزوايا', 'جـ د لأنه يقابل زاوية محيطية متساوية (د أ جـ)', 'أ د لأنه يقابل زاوية مركزية متطابقة القياس', 'لا توجد أقواس متطابقة بناءً على هذه البيانات'], 1], // الزاويتان المحيطيتان متساويتان (30 و 30) إذن الأقواس المقابلة متساوية (ب جـ = جـ د)
    [26, 'mcq', '', 'الزاوية المحيطية المرسومة على قطر الدائرة وتعتبر إحدى زوايا الرباعي الدائري، قياسها:', ['يساوي خمس وأربعين درجة كزاوية حادة جانبية', 'يساوي ستين درجة كزاوية في مثلث متساوي الأضلاع', 'يساوي تسعين درجة وتمثل زاوية قائمة عمودية', 'يساوي مائة وعشرين درجة كزاوية منفرجة علوية'], 2],
    [27, 'mcq', '', 'كل مما يأتي من خواص الرباعي الدائري ما عدا:', ['مجموع كل زاويتين متقابلتين مائة وثمانون درجة', 'الزاوية الخارجة تساوي الداخلة المقابلة للمجاورة', 'الزاويتان المرسومتان على ضلع متساويتان في القياس', 'القطران ينصف كل منهما الآخر بشكل متعامد دائماً'], 3], // الأقطار لا تنصف بعضها في كل الرباعيات الدائرية
    [28, 'mcq', '', 'شكل رباعي دائري أ ب جـ د، فيه أ ب = أ د. فإن:', ['زاوية أ جـ ب تساوي زاوية أ جـ د لمطابقة الأوتار للأقواس', 'زاوية ب أ جـ تساوي زاوية د أ جـ لمطابقة الزوايا المحيطية', 'الوتر ب جـ يوازي الوتر أ د بدون أي تقاطعات هندسية', 'القطر ب د ينصف الزاوية جـ بشكل عمودي مباشر'], 0], // الأوتار المتساوية أ ب، أ د تحصر أقواساً متساوية يقابلها زوايا محيطية متساوية عند الرأس جـ
    [29, 'mcq', '', 'إذا توازى وتران في رباعي دائري، فإن الأقواس المحصورة بينهما:', ['مختلفة الطول باختلاف درجات التوازي المركزي', 'متطابقة ومتساوية في القياس كخاصية من التوازي', 'مجموع قياسهما مائة وثمانون درجة كزاوية مستقيمة', 'تشكل أقواساً متجاورة في نصف الدائرة الأسفل'], 1],
    [30, 'mcq', '', 'في الرباعي الدائري أ ب جـ د، إذا كانت زاوية أ منفرجة، فإن الزاوية جـ المقابلة لها تكون:', ['زاوية منفرجة أيضاً لتطابق الزوايا في الرباعي', 'زاوية قائمة قياسها تسعون درجة كحد أدنى للقياس', 'زاوية حادة لتكملة المجموع إلى مائة وثمانين درجة', 'زاوية مستقيمة تشطر الدائرة إلى نصفين متساويين'], 2], // منفرجة > 90، المكملة يجب أن تكون < 90 (حادة)
    [31, 'mcq', '', 'الرباعي الدائري الذي زواياه الأربع متساوية هو:', ['المعين الذي تتطابق جميع أضلاعه المائلة في القياس', 'متوازي الأضلاع المائل بزوايا حادة ومنفرجة بالترتيب', 'المستطيل أو المربع حيث قياس كل زاوية تسعون درجة', 'شبه المنحرف المتطابق الساقين ذو القواعد المتوازية'], 2],
    [32, 'mcq', '', 'إذا كان القطر أ جـ في الرباعي الدائري أ ب جـ د يمر بالمركز، فإن زاويتي ب و د:', ['كل منهما زاوية قائمة قياسها تسعون درجة هندسية', 'كل منهما زاوية حادة قياسها خمسة وأربعون درجة', 'إحداهما حادة والأخرى منفرجة ومجموعهما مائة وثمانون', 'كل منهما زاوية مستقيمة تمر بمركز الدائرة الهندسية'], 0], // لأنهما محيطيتان مرسومتان في نصف دائرة
    [33, 'mcq', '', 'الشكل الرباعي المكون من أربعة أوتار متساوية الطول في الدائرة يمثل هندسياً:', ['مستطيلاً تتساوى فيه الأضلاع المتقابلة وتتعامد الأقطار', 'مربعاً تتطابق فيه جميع الأضلاع والزوايا الداخلية', 'شبه منحرف عادي لا تتساوى فيه القواعد أو الزوايا', 'طائرة ورقية رباعية ذات أضلاع متجاورة متطابقة'], 1],
    [34, 'mcq', '', 'أ ب جـ د رباعي دائري. إذا رسم مماس من النقطة أ، فإن الزاوية المماسية الناتجة:', ['تساوي الزاوية المحيطية المرسومة على وتر التماس في الرباعي', 'تساوي الزاوية المركزية المقابلة لنفس وتر التماس بالدائرة', 'تساوي مجموع الزوايا الداخلية للرباعي الدائري بالكامل', 'تكون قائمة دائماً لتعامدها مع أضلاع الرباعي المذكور'], 0],
    [35, 'mcq', '', 'زاوية أ = 85 في رباعي دائري. ما هي الزاوية التي لا يمكن أن تساويه في الشكل إذا لم يكن منتظماً؟', ['الزاوية جـ المقابلة لها لأنها يجب أن تكون 95 درجة للمكمل', 'الزاوية ب المجاورة لها لأنها يجب أن تكون 85 درجة للمطابقة', 'الزاوية د المجاورة لها لأنها تتبادل داخلياً مع أ وتساويها', 'الزاوية الخارجة عند الرأس جـ لأنها تطابق الزاوية أ'], 0], // جـ يجب أن تكون 95، فلا يمكن أن تساوي أ (85)
    [36, 'mcq', '', 'إذا كانت النقطة هـ تنتمي للقطعة المستقيمة أ ب الممتدة (شعاع أ ب)، فإن الزاوية هـ ب جـ هي زاوية:', ['محيطية داخلية تقابل القوس الأكبر في الدائرة المحيطة', 'مركزية تقابل الوتر جـ د المار بمركز الدائرة الهندسية', 'خارجة عن الرباعي الدائري أ ب جـ د وتساوي المقابلة لأ', 'خارجة عن الرباعي الدائري وتساوي الزاوية الداخلية أ'], 3], // هـ ب جـ خارجة عند ب = الداخلة عند أ (المقابلة للمجاورة)
    [37, 'mcq', '', 'أي من النسب الآتية يمكن أن تمثل زاويتين متقابلتين في رباعي دائري (حيث مجموعهما 180)؟', ['نسبة 2 : 3 حيث الزوايا 72 و 108 درجات', 'نسبة 1 : 1 حيث الزوايا 60 و 60 درجة', 'نسبة 3 : 5 حيث الزوايا 90 و 150 درجة', 'نسبة 1 : 2 حيث الزوايا 40 و 80 درجة'], 0], // مجموع الأجزاء 5. 180/5=36. 36*2=72, 36*3=108. مجموعهما 180.
    [38, 'mcq', '', 'في الرباعي الدائري أ ب جـ د، زاوية أ جـ ب = زاوية أ د ب = 50، وزاوية جـ ب د = 40، فإن زاوية جـ أ د تساوي:', ['خمسين درجة لتمثل تطابق الزاوية المحيطية على القوس المشترك', 'أربعين درجة لتمثل الزاوية المحيطية المرسومة على نفس القوس جـ د', 'تسعين درجة كناتج لمجموع الزاويتين المذكورتين في المثلث الداخلي', 'مائة وأربعين درجة كزاوية مكملة للرباعي الدائري الخارجي'], 1], // جـ أ د وجـ ب د مرسومتان على القوس جـ د. إذن جـ أ د = جـ ب د = 40
    [39, 'mcq', '', 'إذا رسمنا أقطار الرباعي الدائري، نتجت أزواج من الزوايا المتساوية، عددها الإجمالي:', ['زوجان اثنان فقط من الزوايا المتقابلة بالرأس والمحيطية', 'أربعة أزواج من الزوايا المرسومة على الأضلاع الأربعة كقواعد', 'ستة أزواج من الزوايا المتناظرة والمتبادلة عبر الأقطار المشتركة', 'ثمانية أزواج تمثل كافة زوايا المثلثات الناتجة بالتقاطع'], 1],
    [40, 'mcq', '', 'المثلثان الناتجتان عن تقاطع أقطار الرباعي الدائري واللذان يشتركان في رأس التقاطع يكونان:', ['متطابقين بجميع الزوايا والأضلاع كمثلثات قياسية', 'متشابهين لتساوي زواياهما المحيطية المتقابلة والمتبادلة', 'مختلفين ولا يملكان أي زوايا أو أضلاع متساوية هندسياً', 'قائمي الزاوية في الرأس المشترك لتطابق الأقطار المتعامدة'], 1],

    // --- 10 True/False ---
    [41, 'tf', '', 'في الشكل الرباعي الدائري، كل زاويتين متقابلتين متتامتان ومجموعهما 90 درجة.', false], // متكاملتان (180)
    [42, 'tf', '', 'قياس الزاوية الخارجة عند أي رأس من رؤوس الرباعي الدائري يساوي قياس الزاوية الداخلة المقابلة للمجاورة لها.', true],
    [43, 'tf', '', 'الزاويتان المرسومتان على قاعدة واحدة وفي جهة واحدة منها في الرباعي الدائري تكونان متساويتين في القياس.', true],
    [44, 'tf', '', 'إذا توازى ضلعان متقابلان في رباعي دائري، فإنه بالضرورة يتحول إلى معين متطابق الأضلاع.', false], // يتحول إلى شبه منحرف متساوي الساقين أو مستطيل
    [45, 'tf', '', 'المربع والمستطيل هما من الأشكال الرباعية الدائرية التي تحقق جميع الخواص بامتياز.', true],
    [46, 'tf', '', 'إذا تقاطع قطرا الرباعي الدائري، فإنهما يقسمان زواياه الداخلية إلى أزواج غير متساوية في القياس.', false], // أزواج متساوية (المرسومة على قواعد واحدة)
    [47, 'tf', '', 'يمكن أن يكون الرباعي الدائري مائلاً لدرجة أن يحتوي على زاويتين منفرجتين متقابلتين.', false], // المتقابلتان يجب أن يكون مجموعهما 180، فلا يمكن أن تكونا معاً منفرجتين
    [48, 'tf', '', 'الزاوية الخارجة عن الرباعي الدائري لا يمكن أن تكون زاوية منفرجة تحت أي ظرف هندسي.', false], // يمكن أن تكون منفرجة إذا كانت الداخلة المقابلة للمجاورة منفرجة
    [49, 'tf', '', 'القطران في الرباعي الدائري لا ينصف كل منهما الآخر إلا إذا كان الشكل مستطيلاً أو مربعاً.', true],
    [50, 'tf', '', 'جميع خواص الرباعي الدائري تتحقق في أي مضلع خماسي مرسوم داخل دائرة إذا أخذنا أربعة رؤوس منه فقط.', true]
]);

