window.addBankLesson('bank_math_geom_u5_l6', 'math', 'عكس خواص الشكل الرباعي الدائري', [
    // --- 40 MCQ ---
    [1, 'mcq', '', 'يكون الشكل الرباعي دائرياً إذا وُجدت فيه زاويتان مرسومتان على قاعدة واحدة وفي جهة واحدة منها:', ['متكاملتان ومجموعهما مائة وثمانون درجة هندسية ممتدة', 'متساويتان في القياس الهندسي ومتطابقتان تماماً', 'مختلفتان في القياس بحيث يكون الفرق بينهما تسعين', 'متتامتان ومجموعهما تسعون درجة كزوايا قائمة'], 1],
    [2, 'mcq', '', 'يكون الشكل الرباعي دائرياً إذا وُجدت فيه زاويتان متقابلتان:', ['متطابقتان ومتساويتان في القياس القطعي المستمر', 'متتامتان ومجموعهما تسعون درجة هندسية تامة', 'متكاملتان ومجموع قياسيهما مائة وثمانون درجة', 'متبادلتان وتصنعان حرف زد باللغة الإنجليزية المتصلة'], 2],
    [3, 'mcq', '', 'يكون الشكل الرباعي دائرياً إذا وُجدت زاوية خارجة عند أحد رؤوسه قياسها يساوي:', ['قياس الزاوية الداخلة المجاورة لها على الخط المستقيم', 'قياس الزاوية الداخلة المقابلة للزاوية المجاورة لها', 'مجموع قياسات الزوايا الثلاث الباقية في الشكل المعطى', 'نصف قياس الزاوية المركزية المشتركة في القوس الأكبر'], 1],
    [4, 'mcq', '', 'في الشكل أ ب جـ د، إذا كان قياس الزاوية أ + قياس الزاوية جـ = 180 درجة، فإن الشكل:', ['يجب أن يكون متوازي أضلاع ذو أضلاع متقابلة غير متوازية', 'يعتبر شكلاً رباعياً دائرياً لتحققه من شرط الزوايا المتقابلة', 'يعتبر معيناً متطابق الأضلاع ومختلف الزوايا الداخلية تماماً', 'لا يمكن رسم دائرة تمر برؤوسه لعدم تطابق الزاويتين'], 1],
    [5, 'mcq', '', 'في الشكل أ ب جـ د، إذا كانت الزاوية أ ب د تطابق الزاوية أ جـ د، فماذا نستنتج؟', ['أن الأقطار متعامدة وتنصف بعضها البعض كزوايا المربع', 'أن الشكل أ ب جـ د رباعي دائري لزاويتين على قاعدة أ د', 'أن الشكل أ ب جـ د متوازي أضلاع لتطابق الزوايا الداخلية', 'أن الأضلاع أ ب و جـ د متوازية ولا يمكن أن تتقاطع أبداً'], 1],
    [6, 'mcq', '', 'أي من الشروط الآتية "لا يكفي" لإثبات أن الشكل الرباعي دائري؟', ['وجود زاويتين متقابلتين متكاملتين (مجموعهما 180 درجة)', 'وجود زاوية خارجة تساوي الزاوية الداخلة المقابلة للمجاورة', 'وجود زاويتين متساويتين مرسومتين على قاعدة واحدة وفي جهة واحدة', 'وجود زاويتين متجاورتين متكاملتين (مجموعهما 180 درجة)'], 3], // الزوايا المتجاورة المتكاملة من خواص متوازي الأضلاع وليست دليلاً على الدائرية
    [7, 'mcq', '', 'إذا كانت النقطة م نقطة تقاطع قطري شكل رباعي، وكانت م أ = م ب = م جـ = م د، فإن الشكل:', ['رباعي دائري والمستطيل يمثل إحدى حالاته المؤكدة', 'متوازي أضلاع عادي ولا يمتلك خواص الدائرة الهندسية', 'معين ذي زوايا حادة ومنفرجة ولا تمر به دائرة', 'شبه منحرف عادي ذي أضلاع تختلف في أطوالها القياسية'], 0], // م أ=م ب=م جـ=م د يعني الأقطار متساوية وتنصف بعضها، إذن هو مستطيل والمستطيل دائري
    [8, 'mcq', '', 'إذا ثبت أن شكلاً هو رباعي دائري، فما هي الخطوة اللاحقة التي يمكن تطبيقها رياضياً؟', ['تطبيق نظرية فيثاغورس على جميع أضلاع الشكل الخارجي', 'تطبيق جميع خواص الدائرة والزوايا المحيطية على هذا الشكل', 'استبعاد كافة قوانين الأقواس والأوتار من حسابات الشكل', 'تحويل الشكل إلى مثلثات متطابقة الأضلاع حصراً ومباشرة'], 1],
    [9, 'mcq', '', 'في شبه المنحرف المتساوي الساقين أ ب جـ د، (أ د يوازي ب جـ، أ ب = د جـ). هل هو رباعي دائري؟', ['نعم، لأن زاويتي القاعدة متساويتان مما يجعل الزوايا المتقابلة متكاملة', 'لا، لأن الأضلاع غير المتوازية تمنع انطباق الشكل على محيط الدائرة', 'نعم، لأن جميع أضلاعه الأربعة متساوية في الطول ومتقاطعة بتعامد', 'لا، لأن زواياه المتقابلة تتساوى في القياس ولا تتكامل للوصول לـ 180'], 0], // زاوية ب = زاوية جـ. وبما أن أ تكمل ب، إذن أ تكمل جـ (مجموعهما 180). إذن دائري.
    [10, 'mcq', '', 'إذا رُسم مثلث أ ب جـ، ورُسمت ارتفاعاته لتتقاطع في النقطة و، فإن الأشكال الرباعية المتكونة عند رؤوس المثلث والتي تحتوي على زوايا قائمة هي:', ['أشكال خماسية منتظمة الزوايا لتوازي ارتفاعات المثلث', 'أشكال رباعية غير دائرية لانعدام الأقواس المتساوية بينها', 'أشكال رباعية دائرية لتكامل الزاويتين القائمتين المتقابلتين (90+90=180)', 'أشكال مماسية خارجية تمس دوائر وهمية متعددة دون تقاطع'], 2],
    [11, 'mcq', '', 'في الشكل أ ب جـ د، إذا مُد الضلع أ ب إلى النقطة هـ، فإذا كانت الزاوية جـ ب هـ (الخارجة) = 110، والزاوية د (الداخلة) = 110. فإن:', ['الشكل لا يمثل رباعياً دائرياً لاختلاف مجموع الزوايا المعطاة عن 180', 'الشكل يمثل رباعياً دائرياً لتساوي الزاوية الخارجة مع الداخلة المقابلة للمجاورة', 'القطر أ جـ ينصف الزاوية أ بالتساوي كخاصية لمتوازي الأضلاع المائل', 'الزاوية ب الداخلة لابد أن تساوي مائة وعشر درجات للتطابق المباشر'], 1],
    [12, 'mcq', '', 'أ ب جـ د شكل رباعي، قطراه متعامدان ولكنهما لا ينصفان بعضهما. هل بالضرورة أن يكون دائرياً؟', ['نعم، لأن تعامد الأقطار شرط أساسي وكافٍ للرباعي الدائري', 'لا، تعامد الأقطار (مثل الطائرة الورقية) لا يضمن تكامل الزوايا المتقابلة', 'نعم، لأن جميع الأشكال ذات الأقطار المتعامدة تمر بها دائرة المركز', 'لا، لأن الأقطار يجب أن تكون متوازية بدلاً من متعامدة لتطبيق القاعدة'], 1],
    [13, 'mcq', '', 'لإثبات دائرية الشكل باستخدام الزوايا المحيطية، نقوم برسم أو إيجاد القطرين لـ:', ['تحويل الشكل إلى مستطيل قياسي وتطبيق فيثاغورس على الأضلاع الخارجية', 'البحث عن زاويتين مرسومتين على ضلع واحد كقاعدة ومتساويتين في القياس', 'إلغاء خاصية التقاطع الداخلي وتقسيم الشكل لعدة مثلثات متطابقة', 'تطبيق نظرية المماس الخارجي على زوايا الرباعي المتبادلة والمتوازية'], 1],
    [14, 'mcq', '', 'إذا كانت أ ب جـ د نقاط في مستوى، بحيث الزاوية ب أ جـ لا تساوي الزاوية ب د جـ (وهما في جهة واحدة من ب جـ). فإن:', ['النقاط الأربع تمر بها دائرة واحدة محيطة بها كنقطة التقاء نهائية', 'النقاط الأربع لا تمر بها دائرة واحدة لاختلال شرط الزوايا على قاعدة واحدة', 'الضلعان أ ب و جـ د متوازيان هندسياً ومتباعدان في المسار', 'الأقطار يجب أن تكون متعامدة لتعويض الفرق في قياس الزوايا'], 1],
    [15, 'mcq', '', 'أ ب جـ د متوازي أضلاع. إذا علمنا أن زاوية أ = 90 درجة، فإن الشكل يصبح:', ['معيناً ذا أضلاع متساوية ولا يمر بدائرة لعدم تكامل زواياه المتبادلة', 'مستطيلاً وتتكامل فيه الزوايا المتقابلة (90+90=180) فيصبح رباعياً دائرياً', 'طائرة ورقية رباعية ولا تتحقق فيها شروط الدائرة المتقاطعة الرؤوس', 'مربعاً متطابق الأضلاع لكنه لا يقبل المرور بدائرة المركز نهائياً'], 1],
    [16, 'mcq', '', 'ما هو الاستنتاج عند رسم دائرتين متقاطعتين في أ، ب، ورسم مستقيمين قاطعين يمران بـ أ و ب ليقطعا الدائرتين؟', ['ينتج أشكال رباعية غير دائرية لاختلاف مراكز الدوائر وتفاوت مساحاتها', 'تتشكل أوتار متوازية في الدائرتين بسبب خواص الزوايا المتبادلة للرباعي الدائري', 'تتعامد الأوتار الناتجة مع خط المركزين لتمثل أنصاف أقطار في كلا الدائرتين', 'لا ينتج أي علاقة هندسية لأن المستقيمات القاطعة لا تمر بالمركزين إطلاقاً'], 1], // مسائل الدائرتين المتقاطعتين غالباً تثبت توازي الأوتار بسبب تساوي الزوايا الخارجة والداخلة.
    [17, 'mcq', '', 'لإثبات أن شكلاً رباعياً هو رباعي دائري، هل يمكن الاعتماد على أن أطوال أضلاعه الأربعة متساوية؟', ['نعم، لأن كل شكل أضلاعه متساوية هو مربع دائري بامتياز ووضوح', 'لا، لأن المعين أضلاعه متساوية ولكن زواياه المتقابلة غير متكاملة (ليس دائرياً عاماً)', 'نعم، لأن تساوي الأضلاع يعني تساوي الأقطار بالضرورة الهندسية الحتمية', 'لا، لأن الدائرة لا تمر إلا بالأشكال غير منتظمة الأضلاع والمختلفة الزوايا'], 1],
    [18, 'mcq', '', 'المثلث أ ب جـ مرسوم فيه منصفان لزاويتي ب وجـ يتقاطعان في م. هل الرباعي المتكون دائري؟', ['يعتمد على تقاطع الأعمدة وليس منصفات الزوايا لتكوين زوايا قائمة متكاملة', 'نعم، لأن منصفات الزوايا تشكل دائماً أشكالاً دائرية محيطية وتتكامل زواياها', 'لا، لأن مركز الدائرة الداخلة لا يشكل رباعياً دائرياً مع أضلاع المثلث مباشرة', 'نعم، ولكن فقط إذا كان المثلث متساوي الأضلاع والزوايا بشكل هندسي دقيق'], 0], // عادة الأعمدة (الارتفاعات) هي التي تكون رباعيات دائرية لظهور الزوايا 90.
    [19, 'mcq', '', 'إذا وجدنا أن زاوية أ جـ ب = زاوية أ د ب = 90 درجة، فإن الشكل أ ب جـ د:', ['يعتبر معيناً متطابق الأضلاع تتقاطع أقطاره بتعامد ولا يحقق شروط الدائرية', 'يعتبر رباعياً دائرياً، والقطر أ ب هو قطر للدائرة المارة برؤوسه الهندسية', 'يمثل متوازي أضلاع مائلاً لا توجد به أي زوايا داخلية قائمة أو متكاملة', 'شكل هندسي مستحيل ولا يمكن رسم زاويتين قائمتين على قاعدة واحدة من جهة واحدة'], 1],
    [20, 'mcq', '', 'لتحديد ما إذا كان الشكل الذي أمامك رباعياً دائرياً من خلال الزوايا الخارجية، يجب أن تقيس:', ['الزاوية المحيطية المقابلة للضلع الأكبر وتقارنها بالزاوية المركزية المشتركة', 'الزاوية الخارجة عند الرأس وتقارنها بالزاوية الداخلة المقابلة للمجاورة لها', 'الزوايا المتجاورة وتتأكد أن مجموعها يساوي مائة وثمانين درجة تامة', 'الأقطار المتقاطعة وتتأكد أنها تنصف الزوايا الرأسية بالكامل بشكل متماثل'], 1],
    [21, 'mcq', '', 'في الشكل الرباعي أ ب جـ د، إذا كان المثلث أ ب جـ يطابق المثلث أ د جـ تماماً (أ ب=أ د، ب جـ=د جـ). هل هو دائري؟', ['نعم، دائماً لأنه يمثل مربعاً متطابق الأضلاع والزوايا في جميع الحالات التامة', 'لا، هذا الشكل (طائرة ورقية) زواياه ب و د متساويتان، ولا تتكاملان إلا إذا كانتا 90', 'نعم، لأن تطابق المثلثين يضمن تكامل الزوايا المتبادلة داخلياً بشكل مؤكد', 'لا، لأن التطابق يمنع مرور دائرة خارجية برؤوس الشكل الهندسي המורكب'], 1], // الطائرة الورقية ليست دائرية إلا لو كانت الزاويتان المتقابلتان المتساويتان 90 درجة (180/2)
    [22, 'mcq', '', 'إذا قمنا برسم دائرة تمر بثلاثة رؤوس لشكل رباعي (أ، ب، جـ)، ووجدنا أن الرأس الرابع (د) يقع خارج الدائرة، فهذا يعني:', ['أن زاوية د (الداخلة) أقل من الزاوية التي تجعل الشكل رباعياً دائرياً מתكاملاً', 'أن زاوية د تكمل الزاوية ب وتساوي مائة وثمانين درجة بالتمام والكمال', 'أن الشكل الرباعي هو مستطيل ذو زوايا قائمة كاملة هندسياً ورياضياً', 'أن الأقطار تنصف بعضها البعض في مركز الدائرة الوهمية الخارجة'], 0], // لو كانت بالخارج فالزاوية أقل، لو بالداخل فالزاوية أكبر من المطلوب للتكامل.
    [23, 'mcq', '', 'عكس نظرية الرباعي الدائري تعتبر أداة هندسية تستخدم خصيصاً لـ:', ['حساب مساحة الشكل الرباعي ذي الأضلاع المتفاوتة والمختلفة الأبعاد والزوايا', 'إثبات أن النقاط الأربع تقع على محيط دائرة واحدة باستخدام قياسات الزوايا', 'إثبات أن المثلثات المكونة للشكل هي مثلثات متطابقة الأضلاع حصراً', 'رسم مماسات خارجية للدائرة توازي أقطار الشكل الرباعي المرسوم داخلياً'], 1],
    [24, 'mcq', '', 'إذا أردنا إثبات دائرية شكل بواسطة قاعدة (زاويتان على قاعدة واحدة)، فهل يشترط أن تكون الزاويتان حادتين؟', ['نعم، يجب أن تكون الزاويتان حادتين حصراً لكي تتقاطعا وتكونا الشكل المطلوب', 'لا، يمكن أن تكونا قائمتين أو منفرجتين المهم أن تتساويا في القياس وتكونا في جهة واحدة', 'نعم، لأن الزوايا المنفرجة تتقاطع خارج الدائرة مما يخل بشرط الرباعي الدائري', 'لا، بشرط أن تكون إحداهما حادة والأخرى منفرجة لتكملة المجموعة لـ 180'], 1],
    [25, 'mcq', '', 'أ ب جـ د شكل رباعي، فيه م نقطة تقاطع أقطاره. إذا كان المثلث م أ ب يشابه المثلث م د جـ، فهل الشكل دائري؟', ['لا، لأن تشابه المثلثات המتقابلة بالرأس شرط لمتوازي الأضلاع المائل ذي הזوايا الحادة', 'نعم، لأن التشابه ينتج عنه زاويتان متساويتان (مثل م أ ب و م د جـ) مرسومتان على القاعدة ب جـ', 'لا، لأن تشابه المثلثات لا يضمن تساوي الأضلاع الخارجية للرباعي المتصل', 'نعم، ولكن فقط إذا كانت جميع زوايا المثلثات قائمة ومتكاملة في نفس الوقت'], 1], // زاوية م أ ب = م د جـ وهما مرسومتان على ب جـ، إذن الشكل دائري
    [26, 'mcq', '', 'الرباعي المكون من منصّفات زوايا أي مستطيل داخلية يمثل هندسياً:', ['معيناً ذا أضلاع متساوية ولا تمر به دائرة هندسية لعدم تكامل زواياه', 'مربعاً متطابق الزوايا الداخلية (قوائم) مما يجعله شكلاً رباعياً دائرياً', 'شبه منحرف عادي ذو أضلاع غير منتظمة وقواعد غير متوازية', 'متوازي أضلاع مائل لا تتطابق أقطاره ولا تنصف زواياه المتبادلة'], 1], // منصفات زوايا المستطيل تشكل مربعاً والمربع دائري
    [27, 'mcq', '', 'في الشكل أ ب جـ د، إذا كان مجموع زاويتين متجاورتين يساوي 180 درجة، ومجموع الزاويتين الأخرتين 180 درجة. هل هو دائري؟', ['نعم، لأنه يحقق شرط التكامل بين الزوايا المتجاورة كخاصية أساسية للدائرة', 'هذا شرط توازي ضلعين (متوازي أضلاع أو شبه منحرف) ولا يضمن الدائرية لعدم تقابل الزوايا المتكاملة', 'نعم، لأن مجموع الزوايا الداخلية كلها 360 درجة مما يضمن دائرية الشكل', 'لا، لأن هذا الشرط مستحيل هندسياً في أي مضلع رباعي مغلق الأبعاد'], 1], // التداخل والتجاور يثبت التوازي. التقابل هو الذي يثبت الدائرية.
    [28, 'mcq', '', 'أي من الجمل التالية يعبر بشكل صحيح عن عكس نظرية الرباعي الدائري المعتمدة على الزاوية الخارجة؟', ['إذا تطابقت زاوية خارجة عند أحد رؤوس شكل رباعي مع الزاوية الداخلة المقابلة للمجاورة، كان الشكل دائرياً', 'إذا تكاملت زاوية خارجة مع الزاوية المجاورة لها على الخط، كان الشكل رباعياً دائرياً بالضرورة', 'إذا تساوت الزاوية الخارجة مع نصف مجموع الزوايا الداخلية للشكل، كان الشكل دائرياً مماسياً', 'إذا زادت الزاوية الخارجة عن تسعين درجة هندسية، فإن الشكل يمثل رباعياً دائرياً منتظماً'], 0],
    [29, 'mcq', '', 'شكل رباعي فيه أ ب = جـ د ، و أ د = ب جـ. هل هو دائري؟', ['نعم، لأنه يمثل مربعاً متطابق الأضلاع والزوايا في جميع حالاته', 'هذا متوازي أضلاع، ولا يكون دائرياً إلا إذا كانت إحدى زواياه قائمة (مستطيل)', 'نعم، لأن تساوي الأضلاع المتقابلة شرط كافٍ وافٍ لمرور الدائرة برؤوسه', 'لا، لأن هذا يمثل شبه منحرف غير منتظم لا تتطابق فيه الزوايا'], 1],
    [30, 'mcq', '', 'إذا قيل لك: "أثبت أن النقاط س، ص، ع، ل تقع على دائرة واحدة"، فهذا يترادف تماماً مع سؤال:', ['أثبت أن الشكل س ص ع ل هو متوازي أضلاع متطابق الأبعاد الجبرية', 'أثبت أن الشكل س ص ع ل يمثل شكلاً رباعياً دائرياً يحقق إحدى الخواص العكسية', 'أثبت أن محيط الشكل س ص ع ل يساوي مساحته مضروبة في النسبة ط', 'أثبت أن الأقطار س ع و ص ل متوازيان ولا يتقاطعان في المركز الداخلي'], 1],
    [31, 'mcq', '', 'لإثبات الدائرية عن طريق زاويتين مرسومتين على ضلع واحد، الزاويتان تمثلان في الدائرة الوهمية المارة بهما:', ['زاويتين مماسيتين تلامسان الدائرة من الخارج في نقطتي التماس المحددتين', 'زاويتين مركزيتين تتقاطعان في نقطة الأصل وتمثلان ضعف الأقواس', 'زاويتين محيطيتين تشتركان في نفس القوس الممثل للضلع المشترك كقاعدة', 'زاويتين متقابلتين بالرأس تشكلان أقطاراً كاملة متعامدة على الأوتار'], 2],
    [32, 'mcq', '', 'أ ب جـ د رباعي، فيه أ ب عمودي على ب جـ، و أ د عمودي على د جـ. هل هو دائري؟', ['لا، لأن التعامد يمنع تكامل الزوايا המتقابلة ويعكس قاعدة الدائرة', 'نعم، لأن الزاويتين ب و د قائمتان (مجموعهما 180) متقابلتان، فالشكل دائري قطره أ جـ', 'نعم، لأن التعامد يجعل الشكل معيناً متطابق الأضلاع ومختلف الزوايا المجاورة', 'لا، لأنه يشكل مثلثين منفصلين لا يمكن ربطهما بدائرة خارجية محيطة'], 1],
    [33, 'mcq', '', 'إذا توافرت شروط دائرية الشكل الرباعي، فهل يترتب على ذلك انطباق باقي الخواص عليه فوراً؟', ['نعم، إثبات إحدى الخواص العكسية يجعل الشكل دائرياً وتصبح باقي الخواص متاحة للاستخدام', 'لا، يجب إثبات جميع الخواص الثلاث معاً قبل إقرار وتأكيد دائرية الشكل الرباعي', 'نعم، ولكن تتغير قياسات الزوايا لتصبح جميعها قوائم بشكل هندسي جبري دقيق', 'لا، الدائرية لا تسمح باستخدام الخواص الأخرى إلا في المثلثات المتطابقة حصراً'], 0],
    [34, 'mcq', '', 'أ ب جـ د رباعي، م نقطة داخله. م أ = 3، م ب = 3، م جـ = 3، م د = 4. هل تمر برؤوسه دائرة؟', ['نعم، لأن معظم الرؤوس تبعد مسافات متطابقة تمثل نصف قطر الدائرة', 'لا، يجب أن تكون الأبعاد الأربعة متطابقة تماماً لتصبح النقطة م مركزاً للدائرة المارة بها', 'نعم، والنقطة م تعتبر مركزاً غير منتظم يميل باتجاه الرأس الأخير د', 'لا، لأن الأبعاد يجب أن تكون متزايدة بشكل هندسي لتعويض فرق الزوايا'], 1],
    [35, 'mcq', '', 'عند رسم شكل رباعي غير منتظم بالمسطرة والقلم بشكل عشوائي، فإنه غالباً:', ['سيكون رباعياً دائرياً لسهولة انطباق الزوايا المتقابلة بـ 180 درجة', 'لن يكون رباعياً دائرياً لأن تكامل الزوايا أو تساويها على قاعدة يحتاج لقياسات دقيقة مسبقة', 'سيكون مستطيلاً مائلاً تمر به الدائرة من الخارج وتقطع الأضلاع من المنتصف', 'سيمثل شكلاً مماسياً تمر بداخله دائرة تلامس أضلاعه الأربعة بتساوٍ كامل'], 1],
    [36, 'mcq', '', 'لإثبات أن الشكل س ص ع ل دائري، تم التوصل إلى أن زاوية ص = 100، وزاوية ل = 80. هذا الإثبات يعتمد على:', ['خاصية الزاويتين المرسومتين على قاعدة واحدة وفي جهة واحدة منها بالتطابق', 'خاصية הזاوية الخارجة التي تساوي الداخلة المقابلة للمجاورة لها بالشكل', 'خاصية الزاويتين المتقابلتين المتكاملتين اللتين مجموعهما يساوي مائة وثمانين', 'خاصية الأقطار المتعامدة التي تقسم الشكل إلى مثلثات متشابهة ومتطابقة'], 2],
    [37, 'mcq', '', 'في مسألة ما، كان أ ب جـ د شبه منحرف فيه أ ب // د جـ. وتم إثبات أن زاوية أ = زاوية ب. هذا يثبت أن:', ['الشكل متوازي أضلاع مائل لا ينتمي للرباعيات الدائرية لغياب التقاطع', 'الشكل شبه منحرف متساوي الساقين، وهو شكل رباعي دائري يمكن رسم دائرة تمر برؤوسه', 'الشكل معين تتطابق جميع أضلاعه المتقابلة والمتوازية في الطول والميل', 'الشكل مستطيل لأن جميع زواياه أصبحت بالضرورة زوايا قائمة متتامة'], 1],
    [38, 'mcq', '', 'المثلثان القائما الزاوية المشتركان في وتر واحد كقاعدة (رأساهما في جهة واحدة):', ['لا يمر بهما أي دائرة لاختلاف ميل الأضلاع العمودية وتباين الأقواس الناتجة', 'رؤوسهما الأربعة تمر بها دائرة واحدة قطرها هو الوتر المشترك للقاعدتين', 'يمثلان معيناً متطابق الأضلاع تتقاطع أقطاره بتعامد واضح دون تمركز', 'يشكلان دائرتين منفصلتين متقاطعتين في نقطتي الوتر المشترك كقاعدة'], 1], // مثل زاويتين 90 مرسومتين على نفس الضلع وفي جهة واحدة، الشكل دائري وهذا الضلع هو القطر
    [39, 'mcq', '', 'إذا كان الشكل أ ب جـ د رباعياً دائرياً، وتم توصيل أ جـ، ب د. فإذا علمنا زاوية ب أ جـ = 50، فما الزاوية التي نستنتجها مباشرة من الإثبات؟', ['زاوية ب د جـ تساوي 50 درجة هندسية لاشتراكهما في نفس القاعدة ب جـ', 'زاوية أ جـ د تساوي 130 درجة هندسية للتكامل المتقابل عبر الأقطار المشتركة', 'زاوية د ب أ تساوي 50 درجة هندسية للتبادل الداخلي وتطابق القواطع المركزية', 'زاوية جـ د أ تساوي 90 درجة هندسية لتشكيل زاوية قائمة مكملة للرباعي المذكور'], 0], // مشتركتان في ب جـ
    [40, 'mcq', '', 'أي من النظريات التالية تمثل القاعدة الأساسية العكسية الأكثر شيوعاً في إثبات دائرية الشكل للطلاب؟', ['إذا وجدنا زاويتين متبادلتين متساويتين فإن الشكل رباعي دائري متصل الأضلاع', 'إذا وجدنا زاويتين مرسومتين على ضلع واحد وفي جهة واحدة منه متساويتين في القياس', 'إذا تعامد قطرا الشكل الرباعي وتقاطعا في مركز الشكل وتساويا في الأطوال الجبرية', 'إذا تساوت جميع أضلاع الشكل الرباعي المتقابلة وشكلت زوايا حادة متجاورة'], 1],

    // --- 10 True/False ---
    [41, 'tf', '', 'يكون الشكل الرباعي دائرياً إذا تساوت فيه أي زاويتين متجاورتين في القياس.', false], // متجاورتان لا تثبت الدائرية، المتقابلتان هما اللتان تتكاملان.
    [42, 'tf', '', 'إذا وجدنا زاوية خارجة عند أحد رؤوس الشكل الرباعي تساوي الزاوية الداخلة المقابلة للمجاورة لها، كان الشكل دائرياً.', true],
    [43, 'tf', '', 'إذا كانت زاويتان متقابلتان في شكل رباعي متكاملتين (مجموعهما 180)، فإن الشكل يكون رباعياً دائرياً.', true],
    [44, 'tf', '', 'الرباعي المكون من مثلثين قائمي الزاوية مشتركان في وتر واحد (رأساهما في جهة واحدة) يعتبر رباعياً دائرياً.', true],
    [45, 'tf', '', 'عكس النظريات يستخدم لإثبات أن النقاط الأربع لا تمر بها دائرة.', false], // يستخدم لإثبات أنها "تمر" بها دائرة.
    [46, 'tf', '', 'إذا كانت الأقطار في شكل رباعي لا تنصف الزوايا الرأسية، فلا يمكن أن يكون دائرياً.', false], // المستطيل دائري وأقطاره لا تنصف زواياه.
    [47, 'tf', '', 'تطابق زاويتين مرسومتين على قاعدة واحدة وفي جهة واحدة يكفي لإثبات أن النقاط الأربع تمثل رباعياً دائرياً.', true],
    [48, 'tf', '', 'كل متوازي أضلاع يمكن إثبات أنه رباعي دائري باستخدام خواص الزوايا المتبادلة.', false], // متوازي الأضلاع العادي زواياه المتقابلة متساوية وليست متكاملة.
    [49, 'tf', '', 'في حالة إثبات أن الشكل رباعي دائري، يحق لنا فوراً استخدام كافة خواص الزوايا والأقواس الدائرية عليه.', true],
    [50, 'tf', '', 'شبه المنحرف العادي (مختلف الساقين) يمكن إثبات أنه رباعي دائري إذا كانت زواياه المتقابلة متساوية.', false] // زواياه المتقابلة لن تكون متكاملة في شبه المنحرف المختلف הסاقين.
]);

